import{_ as t}from"./chunks/mo_doc.DhUHWkAB.js";import{_ as n,c as o,o as a,ag as i}from"./chunks/framework.Bzez9NG9.js";const s="/space/img/add_new.png",r="/space/img/mod_doc_menu.png",b=JSON.parse('{"title":"Model documentation","description":"Visualize and maintain IBM Planning Analytics model dependencies, data flows, and relationships across TM1 cubes, TurboIntegrator processes, chores, and other model objects.","frontmatter":{"title":"Model documentation","description":"Visualize and maintain IBM Planning Analytics model dependencies, data flows, and relationships across TM1 cubes, TurboIntegrator processes, chores, and other model objects.","keywords":["IBM Planning Analytics","Planning Analytics","TM1","model documentation","dependency diagram","data lineage","impact analysis","cubes","TurboIntegrator","TI processes","chores"],"outline":"deep"},"headers":[],"relativePath":"doc/planning-analytics/model-documentation.md","filePath":"doc/planning-analytics/model-documentation.md"}'),d={name:"doc/planning-analytics/model-documentation.md"};function l(c,e,m,u,h,p){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="model-documentation" tabindex="-1">Model documentation <a class="header-anchor" href="#model-documentation" aria-label="Permalink to &quot;Model documentation&quot;">​</a></h1><p><strong>Model documentation</strong> gives you an interactive visual map of your IBM Planning Analytics model. SPACE analyzes TM1 metadata and relationships to show how cubes, TurboIntegrator processes, chores, and other model objects are connected, making complex applications easier to understand without manually tracing dependencies through code.</p><p>Use the diagram to explore data flows, understand unfamiliar models, identify dependencies before making changes, support impact analysis, and create documentation for reviews or workshops.</p><p><img src="'+t+'" alt="Model documentation" data-zoomable=""></p><h2 id="creating-and-updating-documentation" tabindex="-1">Creating and updating documentation <a class="header-anchor" href="#creating-and-updating-documentation" aria-label="Permalink to &quot;Creating and updating documentation&quot;">​</a></h2><p>SPACE generates the model documentation from the selected Planning Analytics connection.</p><ol><li>Open <strong>Model documentation</strong> from the SPACE sidebar.</li><li>Use <strong>Refresh documentation</strong> from the three-dot menu to regenerate the diagram from the latest TM1 model metadata. Only administrators or users with the <strong>Documentation update</strong> job permission can run a refresh.</li><li>To keep documentation current automatically, create a <strong>Documentation update</strong> job under <a href="./../configuration/jobs.html">Settings → Jobs</a>.</li></ol><p>Scheduled updates are useful when the model changes regularly or when documentation should be refreshed after development and deployment activity.</p><h2 id="documenting-additional-relationships" tabindex="-1">Documenting additional relationships <a class="header-anchor" href="#documenting-additional-relationships" aria-label="Permalink to &quot;Documenting additional relationships&quot;">​</a></h2><p>Not every important dependency necessarily exists directly in TM1 metadata. You can add relationships manually to capture additional business or technical context, such as an external data feed or another dependency relevant to the model.</p><p>Select <strong>Add new</strong>, then <strong>Link</strong> to create a relationship between source and target nodes.</p><p><img src="'+s+'" alt="Add link menu" data-zoomable=""></p><p>Add a description to explain the relationship and choose a color when you want the custom dependency to stand out in the diagram.</p><h2 id="exploring-the-model" tabindex="-1">Exploring the model <a class="header-anchor" href="#exploring-the-model" aria-label="Permalink to &quot;Exploring the model&quot;">​</a></h2><p>Use the interactive diagram to navigate and understand the model:</p><ul><li><strong>Pan and zoom</strong> through large model diagrams using the mouse or mini map.</li><li><strong>Search</strong> for cubes, processes, subsets, and other objects to locate them quickly.</li><li><strong>Select nodes and connectors</strong> to review or maintain additional information such as descriptions, ownership, and data tags.</li><li><strong>Highlight relationships and flows</strong> when reviewing dependencies or discussing model behavior.</li><li><strong>Show or hide model elements</strong> to focus the diagram on the objects relevant to the current investigation.</li></ul><p>This can be particularly useful when onboarding to an unfamiliar Planning Analytics application or assessing the potential impact of a model change.</p><h2 id="display-options" tabindex="-1">Display options <a class="header-anchor" href="#display-options" aria-label="Permalink to &quot;Display options&quot;">​</a></h2><p>Open the menu in the upper-right corner of the diagram to control which information is displayed.</p><p><img src="'+r+'" alt="Diagram menu" data-zoomable=""></p><p>Available options include:</p><ul><li><strong>System objects</strong> — include TM1 system cubes and processes.</li><li><strong>Cubes with no links</strong> — include cubes for which no relationships are currently identified.</li><li><strong>Processes</strong> — show TurboIntegrator processes.</li><li><strong>Processes with no links</strong> — include processes without identified dependencies.</li><li><strong>Chores</strong> — display chore nodes and their schedules.</li><li><strong>Hidden objects</strong> — reveal objects that have been hidden from the diagram.</li><li><strong>Mini map</strong> — show or hide the diagram overview.</li></ul><p>These options make it easier to move between a broad model overview and a more focused view of a particular part of the application.</p><h2 id="exporting-documentation" tabindex="-1">Exporting documentation <a class="header-anchor" href="#exporting-documentation" aria-label="Permalink to &quot;Exporting documentation&quot;">​</a></h2><p>Use <strong>Download documentation</strong> from the diagram menu to export the current graph as a PNG image.</p><p>The exported diagram can be used in design reviews, workshops, architecture documentation, or other situations where an offline snapshot of the model is useful.</p><h2 id="automating-documentation-updates" tabindex="-1">Automating documentation updates <a class="header-anchor" href="#automating-documentation-updates" aria-label="Permalink to &quot;Automating documentation updates&quot;">​</a></h2><p>The <strong>Documentation update</strong> job can regenerate model documentation automatically on a schedule.</p><p>Configure the Planning Analytics connection and schedule under <a href="./../configuration/jobs.html">Settings → Jobs</a>. This helps keep the dependency diagram aligned with ongoing model changes without requiring users to refresh it manually.</p>',29)]))}const y=n(d,[["render",l]]);export{b as __pageData,y as default};
